#!/usr/bin/env python3
# patch-158-E5: notes (staff + customer-visible) + work order responses
"""
Brings notes + work-order parity to the multi-asset view.

What ships:

  - Work order card: only renders when the appointment has any
    workOrderFields. Display mode + edit mode toggle (matches
    legacy). Identifier field gets special treatment (large mono
    rendering up top, "ID" pill in edit form). Save POSTs the
    full form to the existing save_work_order op which writes/
    upserts TenantAppointmentWorkOrderResponse rows.

  - Notes card with:
    * Textarea + char counter (500 max)
    * "Also show to customer" checkbox (new! see backend change)
    * List of all notes sorted newest-first, with author + time +
      visibility pill + delete button (system notes not deletable)

  - Backend: extended add_note op to accept is_customer_visible.
    Previous behavior hardcoded the visibility to false; now it
    reads the value from the request, defaulting to false. Safe
    extension - legacy callers still get the old behavior.

  - Reuses existing ops: add_note, delete_note, save_work_order.

Notable design choice:
  - Work order responses remain appointment-wide, not per-asset.
    That matches the existing data model. If we want per-asset
    responses later, that's a schema migration adding
    appointment_asset_id to TenantAppointmentWorkOrderResponse.
    Deferred.

Standalone Python. Idempotent.
"""
